<dialog id="vat-action-dialog" class="vat-dialog" aria-labelledby="vat-action-title"><form id="vat-action-form"><header><h2 id="vat-action-title">VAT action</h2><button type="button" data-vat-dismiss aria-label="Close tax summary dialog">×</button></header><p id="vat-action-intro"></p><div class="vat-fields" id="vat-action-fields"></div><p id="vat-action-error" role="alert"></p><div id="vat-action-preview" hidden></div><footer><button type="button" class="button secondary compact" data-vat-dismiss>Cancel</button><button type="submit" class="button secondary compact" id="vat-preview-button">Review preview</button><button type="button" class="button primary compact" id="vat-confirm-button" hidden>Confirm &amp; record</button></footer></form></dialog>
<dialog id="vat-source-dialog" class="vat-dialog" aria-labelledby="vat-source-title"><header><h2 id="vat-source-title">VAT sources</h2><button type="button" data-vat-source-dismiss aria-label="Close source preview">×</button></header><div id="vat-source-body" aria-live="polite"></div></dialog>
